  for v_z in select * from jsonb_array_elements(v_zonas)
  loop
    if exists (
      select 1 from comun_comercio.com_zona_cobertura
       where zon_negocio = 'tinkay'
         and zon_codigo = v_z->>'codigo'
    ) then
      update comun_comercio.com_zona_cobertura
         set zon_nombre = v_z->>'nombre',
             zon_provincia = 'Pichincha',
             zon_modo_cobro = v_z->>'modo_cobro',
             zon_tarifa_fija = (v_z->>'tarifa')::numeric(10,2),
             zon_prioridad = (v_z->>'prioridad')::int,
             zon_activo = true,
             zon_poligono = v_z->'poligono',
             zon_detalle_zona = coalesce(zon_detalle_zona, '{}'::jsonb) || (v_z->'detalle'),
             zon_eliminado_en = null,
             zon_actualizado_en = now()
       where zon_negocio = 'tinkay'
         and zon_codigo = v_z->>'codigo';
    else
      insert into comun_comercio.com_zona_cobertura (
        zon_negocio, zon_codigo, zon_nombre, zon_provincia,
        zon_modo_cobro, zon_tarifa_fija, zon_prioridad, zon_activo,
        zon_poligono, zon_detalle_zona
      ) values (
        'tinkay', v_z->>'codigo', v_z->>'nombre', 'Pichincha',
        v_z->>'modo_cobro', (v_z->>'tarifa')::numeric(10,2), (v_z->>'prioridad')::int, true,
        v_z->'poligono', v_z->'detalle'
      );
    end if;
  end loop;

  -- Sincronizar parámetros y snapshot JSON en comun_configuracion.cfg_negocio
  -- (4 km incluidos × $0.75/km = $3.00 de subsidio base, $0.75/km adicional, mín. $0.75)
  update comun_configuracion.cfg_negocio
     set cfg_detalle_configuracion = jsonb_set(
           jsonb_set(
             jsonb_set(
               jsonb_set(
                 coalesce(cfg_detalle_configuracion, '{}'::jsonb),
                 '{logistica,tarifaPorKm}', '0.75'::jsonb, true
               ),
               '{logistica,subsidioBaseUsd}', '3.00'::jsonb, true
             ),
             '{logistica,recargoMinimoExtra}', '0.75'::jsonb, true
           ),
           '{logistica,zonas}',
           (
             select coalesce(jsonb_agg(
               jsonb_build_object(
                 'id', zon_id::text,
                 'codigo', zon_codigo,
                 'nombre', zon_nombre,
                 'provincia', zon_provincia,
                 'modoCobro', zon_modo_cobro,
                 'tarifaFija', zon_tarifa_fija,
                 'prioridad', zon_prioridad,
                 'activo', zon_activo,
                 'color', coalesce(zon_detalle_zona->>'color', '#16A34A'),
                 'sectoresReferencia', coalesce(zon_detalle_zona->'sectores_referencia', '[]'::jsonb),
                 'poligono', zon_poligono
               ) order by zon_prioridad asc, zon_tarifa_fija asc
             ), '[]'::jsonb)
             from comun_comercio.com_zona_cobertura
             where zon_negocio = 'tinkay'
               and zon_activo = true
               and zon_eliminado_en is null
           ),
           true
         ),
         cfg_actualizado_en = now()
   where cfg_negocio = 'tinkay';
end $$;
